const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function createWeather(seed=1){return[{type:'gust',name:'阵风锋面',x:-200+(seed%5)*80,z:-3350+(seed%7-3)*35,base:320,top:950,width:1300,length:650,strength:.8,phase:seed*.73},{type:'storm',name:'雷暴单体',x:100+(seed%3)*90,z:-5500+(seed%9-4)*30,base:650,top:1350,width:1150,length:670,strength:1,phase:seed*.41},{type:'storm',name:'海风雷暴',x:-250,z:-9300+(seed%5-2)*45,base:550,top:1250,width:1000,length:600,strength:.9,phase:seed*.29}]}
export function sampleWeather(f){const cells=f.weatherCells||[];let intensity=0,active=null;for(const c of cells){const horizontal=clamp(1-Math.abs(f.z-c.z)/c.length,0,1)*clamp(1-Math.abs(f.x-c.x)/c.width,0,1);const vertical=clamp((f.y-c.base)/100,0,1)*clamp((c.top-f.y)/100,0,1);const pulse=.78+.22*Math.sin(f.elapsed*.75+c.phase);const value=horizontal*vertical*c.strength*pulse;if(value>intensity){intensity=value;active=c}}const next=cells.find(c=>c.z<f.z&&f.z-c.z<2100);const phase=active?.phase||0;const wave=Math.sin(f.elapsed*2.8+phase)*.65+Math.sin(f.elapsed*5.7+phase)*.35;return{intensity,type:active?.type||'clear',name:active?.name||'平稳气流',next,windX:wave*18*intensity,windY:(Math.sin(f.elapsed*2.1+phase)*23-(active?.type==='storm'?9:2))*intensity,roll:wave*2.4*intensity,pitch:Math.cos(f.elapsed*3.4+phase)*.5*intensity,lift:1-intensity*.28+wave*intensity*.2,flash:active?.type==='storm'&&intensity>.18&&((f.elapsed+phase)%8)<.13,intensityLabel:intensity>.5?'强':intensity>.2?'中':'轻'};}
